  Theorem read_pre : exists fx5 R5 M5, msteps RSEGS (st fx R 0x6a95c M) (st fx5 R5 0x13e9ec M5) /\ read_mid R5 M5.
  Proof.
    pose proof HC as (C1 & C2 & C3 & C4 & C5 & C6 & C7 & F1 & F2 & F3 & F4 & F5 & F6 & F7 & F8 & FW).
    pose proof (u64_of_zeros M 2147467096 (L5KA.zeros_at_sub M 2147467096 16 2147467096 8 HFMT ltac:(lia) ltac:(lia)) ltac:(lia) ltac:(lia)) as HFMT64.
    pose proof (u64_of_zeros M 2147467104 (L5KA.zeros_at_sub M 2147467096 16 2147467104 8 HFMT ltac:(lia) ltac:(lia)) ltac:(lia) ltac:(lia)) as HFMT64b.
    assert (Pr : 140735332552704 <= p <= 140737488355318) by lia.
    assert (Nr : 0 <= n <= 131071) by lia.
    pose proof (drA_conc fx R M (fun j => match j with 2%nat => S | 33%nat => p | 34%nat => n | _ => 0 end)) as P. cbn beta iota in P.
