    assert (AG23 : forall x : word, bv_unsigned x < S - 3248 \/ S - 112 <= bv_unsigned x -> ~ filew (bv_unsigned x) -> M3 x = M2 x) by (intros x Hx Hf; unfold filew in Hf; apply FR3; lia).
